/// The role of a server status string; NULL or one this version does not know is inactive.
static inline BriareusStatusRole briareus_status_role(const char *status) {
    if (!status) return BRIAREUS_STATUS_INACTIVE;
    if (strcmp(status, "running") == 0 || strcmp(status, "queued") == 0 || strcmp(status, "preparing") == 0 || strcmp(status, "starting") == 0) return BRIAREUS_STATUS_ACTIVE;
    if (strcmp(status, "idle") == 0) return BRIAREUS_STATUS_IDLE;
    if (strcmp(status, "waiting") == 0 || strcmp(status, "interrupted") == 0 || strcmp(status, "cancelled") == 0) return BRIAREUS_STATUS_ATTENTION;
    if (strcmp(status, "failed") == 0 || strcmp(status, "error") == 0) return BRIAREUS_STATUS_FAILED;
    return BRIAREUS_STATUS_INACTIVE;
}

static inline unsigned int briareus_status_color(const BriareusPalette *palette, BriareusStatusRole role) {
    switch (role) {
    case BRIAREUS_STATUS_ACTIVE: return palette->accent;
    case BRIAREUS_STATUS_IDLE: return palette->ok;
    case BRIAREUS_STATUS_ATTENTION: return palette->warn;
    case BRIAREUS_STATUS_FAILED: return palette->danger;
    case BRIAREUS_STATUS_INACTIVE: return palette->dot;
    }
    return palette->dot;
}

